// [Tool] set_interests : nettoyer + valider la liste (issue #13)
// Liste commune : docs/tags.md (= tags des articles)
const ALLOWED = ['espace', 'science', 'ia', 'tech', 'international', 'politique', 'economie', 'sante', 'environnement'];
const SYNONYMS = {
  'intelligence artificielle': 'ia', 'ai': 'ia', 'i.a.': 'ia',
  'technologie': 'tech', 'technologies': 'tech', 'techno': 'tech', 'informatique': 'tech',
  'astronomie': 'espace', 'spatial': 'espace',
  'sciences': 'science',
  'monde': 'international', 'geopolitique': 'international',
  'eco': 'economie', 'finance': 'economie',
  'climat': 'environnement', 'ecologie': 'environnement',
  'medecine': 'sante',
};
const MAX = 10;

const input = $input.first().json;
const userId = input.user_id;

function clean(s) {
  return String(s || '').toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .trim();
}

// Accepte un tableau, un JSON '["a","b"]' ou une chaîne 'a, b'
let raw = input.interests;
if (typeof raw === 'string') {
  const t = raw.trim();
  if (t.startsWith('[')) { try { raw = JSON.parse(t); } catch (e) { raw = t; } }
}
const list = Array.isArray(raw) ? raw : String(raw || '').split(/[,;\n]| et /);

const accepted = [];
const rejected = [];
for (const item of list) {
  const c = clean(item);
  if (!c) continue;
  const tag = ALLOWED.includes(c) ? c : SYNONYMS[c];
  if (tag) { if (!accepted.includes(tag)) accepted.push(tag); }
  else if (!rejected.includes(String(item).trim())) rejected.push(String(item).trim());
}

let ok = true;
let message = '';
if (!userId) {
  ok = false;
  message = "Utilisateur non identifié : impossible de modifier les centres d'intérêt.";
} else if (!accepted.length && rejected.length) {
  ok = false;
  message = `Aucun centre d'intérêt valide. Non disponible(s) : ${rejected.join(', ')}. Choix possibles : ${ALLOWED.join(', ')}.`;
} else if (accepted.length > MAX) {
  ok = false;
  message = `Trop de centres d'intérêt (${accepted.length}), ${MAX} maximum.`;
}

return [{ json: { ok, message, user_id: userId, interests: accepted, rejected } }];

// [Tool] set_interests : réponse { ok, message, data }
const ALLOWED = ['espace', 'science', 'ia', 'tech', 'international', 'politique', 'economie', 'sante', 'environnement'];
const v = $('TOOL - Validate Interests').first().json;
if (!v.ok) return [{ json: { ok: false, message: v.message } }];

const row = $input.first().json;
if (!row || !Array.isArray(row.interests)) {
  return [{ json: { ok: false, message: "La mise à jour a échoué : centres d'intérêt non modifiés." } }];
}

let message = row.interests.length
  ? `Centres d'intérêt enregistrés : ${row.interests.join(', ')}.`
  : "Centres d'intérêt vidés.";
if (v.rejected.length) {
  message += ` Non disponible(s), donc ignoré(s) : ${v.rejected.join(', ')}. Choix possibles : ${ALLOWED.join(', ')}.`;
}
return [{ json: { ok: true, message, data: { interests: row.interests, rejected: v.rejected } } }];
